    ax.plot(t*1e9, P*1e3, color=c, label=f"I₁ = {frac:.1f} I_th")
    ax.axvline(lz.turn_on_delay(frac*24e-3, 48e-3, 24e-3, 2.5e-9)*1e9, color=c, ls="--", lw=1)
ax.set(xlabel="time (ns)", ylabel="P_o (mW)"); ax.legend(fontsize=8); plt.show()
